package service

import (
	"fmt"
	"sync"
)

// User represents a user in the system
type User struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

// Service provides user-related business logic.
type Service struct {
	users  map[string]User
	mutex  sync.RWMutex
	nextID int
}

// NewService creates and returns a new Service instance.
func NewService() *Service {
	return &Service{
		users:  make(map[string]User),
		nextID: 1,
	}
}

// GetAllUsers returns all registered users.
func (s *Service) GetAllUsers() []User {
	s.mutex.RLock()
	defer s.mutex.RUnlock()

	var list []User
	for _, u := range s.users {
		list = append(list, u)
	}
	return list
}

// CreateUser creates a new user and adds it to the system.
func (s *Service) CreateUser(u User) User {
	s.mutex.Lock()
	defer s.mutex.Unlock()

	u.ID = fmt.Sprintf("%d", s.nextID)
	s.nextID++
	s.users[u.ID] = u
	return u
}

// GetUserByID returns a user by their ID.
func (s *Service) GetUserByID(id string) (User, bool) {
	s.mutex.RLock()
	defer s.mutex.RUnlock()

	u, ok := s.users[id]
	return u, ok
}

package api

import (
	"encoding/json"
	"net/http"
	"strings"

	"legacy_refactor/rep-1/internal/service"
)

// API holds the dependencies for our HTTP handlers.
type API struct {
	service *service.Service
}

// NewAPI creates and returns a new API instance.
func NewAPI(s *service.Service) *API {
	return &API{service: s}
}

// HandleUsers manages requests to the /users endpoint.
func (a *API) HandleUsers(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case http.MethodGet:
		a.getAllUsers(w, r)
	case http.MethodPost:
		a.createUser(w, r)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

func (a *API) getAllUsers(w http.ResponseWriter, r *http.Request) {
	users := a.service.GetAllUsers()
	json.NewEncoder(w).Encode(users)
}

func (a *API) createUser(w http.ResponseWriter, r *http.Request) {
	var u service.User
	if err := json.NewDecoder(r.Body).Decode(&u); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	createdUser := a.service.CreateUser(u)
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(createdUser)
}

// HandleUserByID manages requests to the /users/{id} endpoint.
func (a *API) HandleUserByID(w http.ResponseWriter, r *http.Request) {
	id := strings.TrimPrefix(r.URL.Path, "/users/")
	switch r.Method {
	case http.MethodGet:
		a.getUserByID(w, r, id)
	default:
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

func (a *API) getUserByID(w http.ResponseWriter, r *http.Request, id string) {
	u, ok := a.service.GetUserByID(id)
	if !ok {
		http.NotFound(w, r)
		return
	}
	json.NewEncoder(w).Encode(u)
}

package main

import (
	"log"
	"net/http"

	"experiment/internal/api"
	"experiment/internal/service"
)

func main() {
	// Initialize the service layer
	svc := service.NewService()

	// Initialize the API handlers with the service
	apiHandlers := api.NewAPI(svc)

	// Register HTTP handlers
	http.HandleFunc("/users", apiHandlers.HandleUsers)
	http.HandleFunc("/users/", apiHandlers.HandleUserByID)

	log.Println("Server starting on :8080...")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}

package service

import (
	"testing"
)

func TestService_CreateUser(t *testing.T) {
	svc := NewService()

	u := User{Name: "Test User", Email: "test@example.com"}
	createdUser := svc.CreateUser(u)

	if createdUser.ID == "" {
		t.Error("Expected user ID to be set, got empty")
	}

	if createdUser.Name != u.Name || createdUser.Email != u.Email {
		t.Errorf("Expected user name and email to match, got %v", createdUser)
	}

	if createdUser.ID != "1" {
		t.Errorf("Expected first user ID to be \"1\", got %s", createdUser.ID)
	}

	u2 := User{Name: "Test User 2", Email: "test2@example.com"}
	createdUser2 := svc.CreateUser(u2)

	if createdUser2.ID != "2" {
		t.Errorf("Expected second user ID to be \"2\", got %s", createdUser2.ID)
	}
}

func TestService_GetAllUsers(t *testing.T) {
	svc := NewService()

	users := svc.GetAllUsers()
	if len(users) != 0 {
		t.Errorf("Expected 0 users, got %d", len(users))
	}

	svc.CreateUser(User{Name: "User 1"})
	svc.CreateUser(User{Name: "User 2"})

	users = svc.GetAllUsers()
	if len(users) != 2 {
		t.Errorf("Expected 2 users, got %d", len(users))
	}
}

func TestService_GetUserByID(t *testing.T) {
	svc := NewService()

	u1 := svc.CreateUser(User{Name: "User 1", Email: "user1@example.com"})
	u2 := svc.CreateUser(User{Name: "User 2", Email: "user2@example.com"})

	// Test existing user
	foundUser, ok := svc.GetUserByID(u1.ID)
	if !ok {
		t.Errorf("Expected to find user with ID %s", u1.ID)
	}
	if foundUser.Name != u1.Name {
		t.Errorf("Expected user name %s, got %s", u1.Name, foundUser.Name)
	}

	// Test non-existing user
	_, ok = svc.GetUserByID("nonexistent")
	if ok {
		t.Error("Expected not to find a non-existent user")
	}
}

package api

import (
	"bytes"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"testing"

	"experiment/internal/service"
)

func TestHandleUsers(t *testing.T) {
	svc := service.NewService()
	apiHandlers := NewAPI(svc)

	// Test POST /users (Create User)
	user := service.User{Name: "Alice", Email: "alice@example.com"}
	jsonUser, _ := json.Marshal(user)
	req, err := http.NewRequest(http.MethodPost, "/users", bytes.NewBuffer(jsonUser))
	if err != nil {
		t.Fatal(err)
	}
	rec := httptest.NewRecorder()

	apiHandlers.HandleUsers(rec, req)

	if rec.Code != http.StatusCreated {
		t.Errorf("Expected status %d, got %d", http.StatusCreated, rec.Code)
	}

	var createdUser service.User
	if err := json.NewDecoder(rec.Body).Decode(&createdUser); err != nil {
		t.Fatal(err)
	}
	if createdUser.ID == "" || createdUser.Name != "Alice" {
		t.Errorf("Unexpected created user: %v", createdUser)
	}

	// Test GET /users (Get All Users)
	req, err = http.NewRequest(http.MethodGet, "/users", nil)
	if err != nil {
		t.Fatal(err)
	}
	rec = httptest.NewRecorder()

	apiHandlers.HandleUsers(rec, req)

	if rec.Code != http.StatusOK {
		t.Errorf("Expected status %d, got %d", http.StatusOK, rec.Code)
	}

	var users []service.User
	if err := json.NewDecoder(rec.Body).Decode(&users); err != nil {
		t.Fatal(err)
	}
	if len(users) != 1 || users[0].Name != "Alice" {
		t.Errorf("Unexpected users list: %v", users)
	}
}

func TestHandleUserByID(t *testing.T) {
	svc := service.NewService()
	apiHandlers := NewAPI(svc)

	// Create a user first
	user := service.User{Name: "Bob", Email: "bob@example.com"}
	createdUser := svc.CreateUser(user)

	// Test GET /users/{id} (Existing User)
	req, err := http.NewRequest(http.MethodGet, "/users/"+createdUser.ID, nil)
	if err != nil {
		t.Fatal(err)
	}
	rec := httptest.NewRecorder()

	apiHandlers.HandleUserByID(rec, req)

	if rec.Code != http.StatusOK {
		t.Errorf("Expected status %d, got %d", http.StatusOK, rec.Code)
	}

	var fetchedUser service.User
	if err := json.NewDecoder(rec.Body).Decode(&fetchedUser); err != nil {
		t.Fatal(err)
	}
	if fetchedUser.ID != createdUser.ID || fetchedUser.Name != createdUser.Name {
		t.Errorf("Unexpected fetched user: %v", fetchedUser)
	}

	// Test GET /users/{id} (Non-Existing User)
	req, err = http.NewRequest(http.MethodGet, "/users/999", nil)
	if err != nil {
		t.Fatal(err)
	}
	rec = httptest.NewRecorder()

	apiHandlers.HandleUserByID(rec, req)

	if rec.Code != http.StatusNotFound {
		t.Errorf("Expected status %d, got %d", http.StatusNotFound, rec.Code)
	}
}

